declare module '@strapi/strapi' {
  export module Public {
    export interface ComponentSchemas {
      'home.hero': HomeHero;
      'lesson.lesson-card': LessonLessonCard;
      'shared.cta': SharedCta;
      'shared.section': SharedSection;
      'shared.social-link': SharedSocialLink;
    }
  }
}
